/**
 * The structure map page. It renders `backend/test/fixtures/structureReplay.json`,
 * generated by `backend/tools/fixtures/structureFixture.ts` and held to the
 * engine's current output by `backend/test/structureReplay.test.ts`.
 */
import { describe, expect, test, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, waitFor, fireEvent, within } from '@testing-library/react'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'

const fixture = JSON.parse(readFileSync(join(__dirname, '..', '..', 'backend', 'test', 'fixtures', 'structureReplay.json'), 'utf8'))

let calls: any[] = []
function mockApi(response: unknown, ok = true, status = 200) {
  calls = []
  vi.doMock('@/lib/apiFetch', () => ({
    apiFetch: vi.fn(async (path: string, init: any) => { calls.push({ path, init }); return { ok, status, json: async () => response } }),
  }))
}
beforeEach(() => vi.resetModules())
afterEach(() => vi.doUnmock('@/lib/apiFetch'))

const file = () => new File(['timestamp,open,high,low,close,volume\n'], 'bars.csv', { type: 'text/csv' })

describe('structure map page', () => {
  test('required inputs are named and nothing is sent; no convention default; half a pair is refused', async () => {
    const { missingStructureInputs } = await import('@/components/structure/StructureReplay')
    const base = { symbol: 'SPY', pairSymbol: '', file: 'x', pairFile: null, marks: 'OPEN' as const }
    expect(missingStructureInputs(base)).toEqual([])
    expect(missingStructureInputs({ ...base, marks: '' })).toEqual(['Timestamp convention'])
    expect(missingStructureInputs({ ...base, pairSymbol: 'QQQ' })).toEqual(['CSV for the pair'])
    expect(missingStructureInputs({ ...base, pairFile: 'y' })).toEqual(['Pair symbol for the pair CSV'])
    expect(missingStructureInputs({ ...base, pairSymbol: 'spy', pairFile: 'y' })).toEqual(['A pair different from the symbol'])
    mockApi(fixture)
    const { StructureReplay } = await import('@/components/structure/StructureReplay')
    render(<StructureReplay />)
    expect((screen.getByText('ANALYSE') as HTMLButtonElement).disabled).toBe(true)
    expect(screen.getByRole('status').textContent).toBe('Required: Symbol · CSV for the symbol · Timestamp convention')
    expect(screen.getByText(/not signals/)).toBeDefined()
    expect(calls.length).toBe(0)
  })

  test('a run posts the convention and both files, and renders the recorded report', async () => {
    mockApi(fixture)
    const { StructureReplay } = await import('@/components/structure/StructureReplay')
    render(<StructureReplay />)
    fireEvent.change(screen.getByLabelText('Symbol'), { target: { value: 'spy' } })
    fireEvent.change(screen.getByLabelText('Pair symbol'), { target: { value: 'QQQ' } })
    fireEvent.change(screen.getByLabelText('Timestamp convention'), { target: { value: 'OPEN' } })
    fireEvent.change(screen.getByLabelText('CSV for the symbol'), { target: { files: [file()] } })
    fireEvent.change(screen.getByLabelText('CSV for the pair'), { target: { files: [file()] } })
    await waitFor(() => expect((screen.getByText('ANALYSE') as HTMLButtonElement).disabled).toBe(false))
    fireEvent.click(screen.getByText('ANALYSE'))
    await waitFor(() => expect(screen.getByText(fixture.report.scope)).toBeDefined())
    expect(calls[0].path).toBe('/api/setups/structure')
    const body = JSON.parse(calls[0].init.body)
    expect(body.config).toEqual({ symbol: 'SPY', pairSymbol: 'QQQ', timestampMarks: 'OPEN' })
    expect(Object.keys(body.csv).sort()).toEqual(['QQQ', 'SPY'])
    expect(screen.getByText(new RegExp(fixture.report.methodVersion))).toBeDefined()
    for (const n of fixture.report.notComputed) expect(screen.getAllByText(n.name).length).toBeGreaterThan(0)
  })

  test('every row is an event the backend sent, with its knownAt in New York time; filtering by kind narrows to that kind', async () => {
    const { StructureReportView, fmtEt, STRUCTURE_ROW_CAP } = await import('@/components/structure/StructureReplay')
    const { container } = render(<StructureReportView report={fixture.report} />)
    const rows = container.querySelectorAll('tbody tr')
    expect(rows.length).toBe(Math.min(STRUCTURE_ROW_CAP, fixture.report.events.length))
    const first = fixture.report.events[0]
    expect(within(rows[0] as HTMLElement).getByText(fmtEt(first.knownAt))).toBeDefined()
    expect(fmtEt(Date.UTC(2026, 0, 5, 14, 31))).toBe('01/05/2026, 09:31 ET')
    fireEvent.change(screen.getByLabelText('Event kind'), { target: { value: 'BOS' } })
    const bos = container.querySelectorAll('tbody tr')
    expect(bos.length).toBe(fixture.report.counts.byKind.BOS)
    for (const r of Array.from(bos)) expect(r.getAttribute('data-kind')).toBe('BOS')
  })

  test('the row cap is stated, never silent', async () => {
    const { StructureReportView, STRUCTURE_ROW_CAP } = await import('@/components/structure/StructureReplay')
    const many = { ...fixture.report, events: Array.from({ length: STRUCTURE_ROW_CAP + 7 }, (_, i) => ({ ...fixture.report.events[0], id: `x${i}` })) }
    render(<StructureReportView report={many} />)
    expect(screen.getByRole('note').textContent).toContain(`Showing ${STRUCTURE_ROW_CAP} of ${STRUCTURE_ROW_CAP + 7}`)
  })

  test('the summary shows only fields the event carries, and invents none', async () => {
    const { eventSummary } = await import('@/components/structure/StructureReplay')
    expect(eventSummary({ id: 'a', kind: 'BOS', symbol: 'SPY', knownAt: 1, methodVersion: 'm', direction: 'UP', broken: { kind: 'SWING_HIGH', price: 591.35 }, close: 591.91 }))
      .toBe('direction UP · broken SWING_HIGH 591.35 · close 591.91')
    expect(eventSummary({ id: 'a', kind: 'X', symbol: 'SPY', knownAt: 1, methodVersion: 'm' })).toBe('')
    expect(eventSummary({ id: 'a', kind: 'X', symbol: 'SPY', knownAt: 1, methodVersion: 'm', price: null })).toBe('')
  })

  test('a refusal is shown by name', async () => {
    mockApi({ status: 'REFUSED', reasons: ['config.timestampMarks: must be OPEN or CLOSE (no default)'] }, false, 400)
    const { StructureReplay } = await import('@/components/structure/StructureReplay')
    render(<StructureReplay />)
    fireEvent.change(screen.getByLabelText('Symbol'), { target: { value: 'SPY' } })
    fireEvent.change(screen.getByLabelText('Timestamp convention'), { target: { value: 'OPEN' } })
    fireEvent.change(screen.getByLabelText('CSV for the symbol'), { target: { files: [file()] } })
    await waitFor(() => expect((screen.getByText('ANALYSE') as HTMLButtonElement).disabled).toBe(false))
    fireEvent.click(screen.getByText('ANALYSE'))
    await waitFor(() => expect(screen.getByRole('alert').textContent).toContain('config.timestampMarks'))
  })
})
